"""Chinese alternatives and partner recovery, appended without renumbering JX1."""
from catalog import *


def append_events():
    if any(e.key == "china_limited" for e in EVENTS):return
    coastal = control(1337)+" "+control(1338)+" "+control(1317)
    offer = active()+" "+war("CHI")+" "+coastal+" lost_national = { country = CHI value = 35 } NOT = { flag = JX_CHINA_LIMITED_PENDING flag = JX_CHINA_LIMITED_WAIT flag = JX_CHINA_LIMITED_DONE flag = JX_CHINA_LIMITED_DISMISSED flag = JX_china_PENDING flag = JX_china_SETTLED }"
    event("china_limited","A limited peace with Nationalist China", "Japan holds Nanjing, Shanghai and Wuhan, and China has lost at least 35 percent of its national territory. A limited peace can end this war before the western capital falls.\n\nChina remains independent, keeps its surviving army and grants Japanese access. Japan retains Shanghai only if it is Chinese-owned and Japanese-held. Other occupied Chinese land returns to China. Communist and regional wars are separate. This closes neither a later war nor a later puppet settlement, but a two-year non-aggression treaty must be respected or explicitly broken.",decision=True,gate=offer,year=1937,persistent=True,actions=[Action("Offer limited terms; do not demand a puppet",[flag("CHINA_LIMITED_PENDING"),later("china_limited_offer",1,"CHI")],chance=100),Action("Continue the war; ask again in three months",[flag("CHINA_LIMITED_WAIT"),later("china_limited_return",90)]),Action("Pursue a decisive victory; dismiss limited peace",[flag("CHINA_LIMITED_DISMISSED")])],art="diplomacy",module="china")
    event("china_limited_offer","China considers a limited peace","A limited settlement preserves the Chinese state and its surviving forces. Shanghai is the sole proposed permanent Japanese concession. China leaves its current alliance wars; Japan's other wars continue. Further resistance remains possible after the treaty period.",country="CHI",triggered=True,actions=[Action("Accept the limited terms",[later("china_limited_accept",1,"CHI")],gate=coastal,chance=60),Action("Continue the resistance",[later("china_limited_refused",1)],chance=40)],art="diplomacy",module="china")
    event("china_limited_accept","The Chinese ceasefire", "China leaves its former alliance and makes a separate peace. Japanese troops retain access. Shanghai transfers only if it is Chinese-owned and Japanese-held when the terms take effect. Other occupied Chinese territory returns to China under the white peace.",country="CHI",triggered=True,actions=[Action("Put the ceasefire into effect",[cond(control(1338)+" "+owned(1338,"CHI"),cmd("secedeprovince",which="JAP",value=1338,when=1)),cond("ispuppet = CHI",cmd("end_puppet")),cmd("leave_alliance",when=1),cmd("peace",which="JAP",value=1),cmd("access",which="JAP"),cmd("non_aggression",which="CHI",where="JAP",when=720),later("china_limited_signed",2)],chance=100)],art="diplomacy",module="china")
    good="NOT = { "+war("CHI")+" } access = { country = CHI country = JAP }"
    event("china_limited_signed","The limited Chinese peace is in force","Nationalist China remains independent and grants Japan access. There is a two-year non-aggression treaty. Japan's wars with other Chinese states continue unless settled separately. A future puppet settlement still requires a new war and a deeper victory.",triggered=True,actions=[Action("Respect the settlement",[clear("CHINA_LIMITED_PENDING"),flag("CHINA_LIMITED_DONE")],gate=good,chance=100),Action("The agreement failed; try again later",[clear("CHINA_LIMITED_PENDING"),flag("CHINA_LIMITED_WAIT"),later("china_limited_return",90)],gate="NOT = { AND = { "+good+" } }")],art="diplomacy",module="china")
    event("china_limited_refused","China refuses the limited terms","The war continues. There is no territory transfer or Japanese dissent penalty. Another offer can be made after three months if the military requirements still hold.",triggered=True,actions=[Action("Continue the campaign",[clear("CHINA_LIMITED_PENDING"),flag("CHINA_LIMITED_WAIT"),later("china_limited_return",90)],chance=100)],art="diplomacy",module="china")
    event("china_limited_return","The Chinese peace offer can be reconsidered","",triggered=True,actions=[Action("",[clear("CHINA_LIMITED_WAIT")])],module="china")

    # Regional releases are optional after a unified settlement. The builder
    # derives exact, disjoint province lists from clean Blood and Iron data.
    for key,tag,name,cap in [("guangxi","CGX","Guangxi",1378),("yunnan","CYN","Yunnan",1390)]:
        event(key+"_autonomy",f"A separate government in {name}",f"Split {name} from the Chinese puppet into a smaller Japanese puppet. Only its listed homeland provinces owned by China will pass to it. Japan's bases and armies remain Japanese. The new state joins Japan's wars and grants access; China loses cores on the transferred regional land.\n\nThis trades a larger unified Chinese economy for another local partner. Japan supplies 1,000 supplies and 100 money. You may instead keep China unified permanently.",decision=True,gate=active()+" "+puppet("U87")+f" NOT = {{ exists = {tag} flag = JX_{key}_REGIONAL_DONE flag = JX_{key}_REGIONAL_PENDING }} "+owned(cap,"U87")+" "+control(cap,"U87"),ready="money = 100 supplies = 1000",year=1937,actions=[Action(f"Create the {name} partner",[money(-100),supplies(-1000),flag(key+"_REGIONAL_PENDING"),later(key+"_release",1,"U87")],chance=0),Action("Keep China unified; dismiss this offer",[flag(key+"_REGIONAL_DONE")],chance=100)],art="asia",module="china")
        event(key+"_release",f"{name} receives a local government","",country="U87",triggered=True,actions=[Action("",[cmd("independence",which=tag,value=1,when=0),later(key+"_commit",2)],gate=f"flag = JX_{key}_REGIONAL_PENDING "+owned(cap,"U87")+" "+control(cap,"U87"),chance=100),Action("",[later(key+"_refund",1)],gate="NOT = { AND = { "+owned(cap,"U87")+" "+control(cap,"U87")+" } }")],module="china")
        event(key+"_commit",f"{name}: establish the Japanese partnership","",triggered=True,actions=[Action("",[cmd("make_puppet",which=tag),later(key+"_local",1,tag),later(key+"_confirmed",3)],gate=f"exists = {tag}",chance=100),Action("",[later(key+"_refund",1)],gate=f"NOT = {{ exists = {tag} }}")],module="china")
        event(key+"_local",f"{name} joins the Japanese partnership",f"The regional government grants access and receives the Japanese development grant. It uses its existing institutions and recruits at home. It joins Japan's existing wars as a puppet.",country=tag,triggered=True,actions=[Action("Put the agreement into effect",[cmd("access",which="JAP"),supplies(1000),money(100),cmd("manpowerpool",value=20),cmd("ai",which='"jx/partner_land.ai"'),cmd("build_division",which="infantry",when=2)],chance=100)],art="asia",module="china")
        valid=puppet(tag)+f" access = {{ country = {tag} country = JAP }}"
        event(key+"_confirmed",f"{name}: the partnership is in force",f"{name} is a Japanese puppet and grants access. Its local industry and territory belong to it. China retains the rest of its territory. Japan's other wars continue.",triggered=True,actions=[Action("The regional agreement is complete",[flag(key+"_REGIONAL_DONE"),clear(key+"_REGIONAL_PENDING")],gate=valid,chance=100),Action("The agreement failed; return the Japanese payment",[money(100),supplies(1000),clear(key+"_REGIONAL_PENDING"),flag(key+"_REGIONAL_DONE")],gate="NOT = { AND = { "+valid+" } }")],art="asia",module="china")
        event(key+"_refund",f"{name}: the release could not be completed",f"The required regional capital was lost or a local government could not be created. The Japanese payment is returned. No completed regional partnership has been recorded.",triggered=True,actions=[Action("Recover the funds",[money(100),supplies(1000),clear(key+"_REGIONAL_PENDING")],gate=f"flag = JX_{key}_REGIONAL_PENDING",chance=100)],art="asia",module="china")

    event("india_recovery","An Indian army for the new state","A small Indian partner receives a finite recruitment reserve and six ordinary infantry production orders. An existing army of twelve or more divisions receives supplies instead. There is no transfer of Indian manpower to Japan.",country="IND",gate="flag = JX_ACTIVE "+puppet("IND")+" NOT = { flag = JX_INDIA_RECOVERY }",year=1941,actions=[Action("Begin local military reconstruction",[flag("INDIA_RECOVERY"),supplies(1800),cond("NOT = { army = { country = IND size = 12 when = 1 } }",cmd("manpowerpool",value=80)),cond("NOT = { army = { country = IND size = 12 when = 1 } }",cmd("build_division",which="infantry",when=6)),later("india_air_recovery",180,"IND")],chance=100)],art="army",module="partners")
    event("india_air_recovery","Air defence for the Indian partner","India receives a finite reserve and two fighter production orders if it lacks four aircraft formations and has the manpower. The units require ordinary Indian IC, supply and construction time.",country="IND",triggered=True,actions=[Action("Build regional air defence",[cmd("manpowerpool",value=8),cmd("build_division",which="interceptor",when=2),supplies(800)],gate=puppet("IND")+" NOT = { air = { country = IND size = 4 when = 1 } }",chance=100),Action("Support the forces already in service",[supplies(800)],gate="OR = { NOT = { "+puppet("IND")+" } air = { country = IND size = 4 when = 1 } }")],art="air",module="partners")

    # Append receivers after the original catalogue so existing event IDs stay
    # stable. A stub puppet and its defeated predecessor can coexist in B&I.
    for key,old,tag in [('china','CHI','U87'),('india','U02','IND'),('indonesia','U05','INO')]:
        valid=f'flag = JX_{key}_PENDING exists = {old} exists = {tag}'
        event(key+'_merge','Unite the national government','',country=tag,triggered=True,actions=[Action('',[cond(f'ispuppet = {tag}',cmd('end_puppet')),cmd('leave_alliance',when=1),cmd('inherit',which=old,value=1)],gate=valid,chance=100),Action('',[],gate='NOT = { AND = { '+valid+' } }')],module='settlements',purpose='Consolidate an already existing recipient with its defeated predecessor before mastery, access and base verification. Explicit inherit value=1 requests transfer of units and production queues; engine confirmation remains required.')


append_events()
